WITH parsed AS (SELECT id, created_at, coupon_codes, attributes['device'] AS device, attributes['gift'] AS gift, ARRAY_MAX(TRANSFORM(items, li -> li.price)) AS max_item_price, TRANSFORM(items, li -> li.product_id) AS product_ids FROM carts) SELECT id, created_at, coupon_codes, device, gift, max_item_price, product_ids, SUM(max_item_price) OVER (ORDER BY max_item_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_item_price, CUME_DIST() OVER (ORDER BY max_item_price DESC) AS max_item_price_cume_dist, COUNT(max_item_price) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS max_item_price_count_30m, COUNT(max_item_price) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS max_item_price_count_30m_2 FROM parsed;
